// GENERATED by scripts/build-plugin.js from src/pkjs/trips.js and
// src/plugin/main.js -- edit those, then run `npm run sync:plugin`.

const trips = (() => {
	const module = { exports: {} };
	// Pure SIRI helpers for A->B trips and the PRIM call guard -- no Pebble,
	// XMLHttpRequest or localStorage access, so test/*.test.js can run them
	// under plain Node. Field shapes: docs/idfm-api-reference.md ("SNCF
	// journey fields used for A->B trips").
	// No `?.` / `??` here: the SDK's webpack 1 bundler predates ES2020.

	/**
	 * @param {object} journey - A SIRI MonitoredVehicleJourney.
	 * @returns {string[]} Every identity key available for this train: the
	 *   dated journey ref first, then the train number. Several keys so a
	 *   train missing one of them on one side still matches on the other.
	 */
	function journeyKeys(journey) {
		const keys = [];
		const framed = journey.FramedVehicleJourneyRef;
		if (framed && framed.DatedVehicleJourneyRef) {
			keys.push("ref:" + framed.DatedVehicleJourneyRef);
		}
		const numbers = journey.TrainNumbers
			? journey.TrainNumbers.TrainNumberRef
			: null;
		const number = (numbers || [])[0];
		if (number && number.value) keys.push("num:" + number.value);
		return keys;
	}

	/**
	 * @param {object} call - A SIRI MonitoredCall.
	 * @returns {number|null} Epoch ms of the best available time field, or
	 *   null (same field order as callMinutesRemaining in index.js).
	 */
	function callTimeMs(call) {
		const field =
			call.ExpectedArrivalTime ||
			call.ExpectedDepartureTime ||
			call.AimedArrivalTime ||
			call.AimedDepartureTime;
		if (!field) return null;
		const ms = new Date(field).getTime();
		return Number.isNaN(ms) ? null : ms;
	}

	/**
	 * @param {object} callA - The train's MonitoredCall at A.
	 * @param {object} callB - The same train's MonitoredCall at B.
	 * @returns {boolean} True when the train reaches B after A: by stop
	 *   sequence (`Order`) when both sides have it, by time otherwise.
	 */
	function reachesBAfterA(callA, callB) {
		if (typeof callA.Order === "number" && typeof callB.Order === "number") {
			return callB.Order > callA.Order;
		}
		const timeA = callTimeMs(callA);
		const timeB = callTimeMs(callB);
		return timeA !== null && timeB !== null && timeB > timeA;
	}

	/**
	 * @param {object} visit - A SIRI MonitoredStopVisit.
	 * @returns {boolean} True when it has the fields the A->B join needs.
	 */
	function isUsableVisit(visit) {
		const journey = visit && visit.MonitoredVehicleJourney;
		return !!(journey && journey.MonitoredCall);
	}

	/**
	 * @param {object[]} visitsA - MonitoredStopVisit list at the boarding stop.
	 * @param {object[]} visitsB - MonitoredStopVisit list at the arrival stop
	 *   (both directions mixed, as a stop area returns them).
	 * @returns {object[]} The visits of `visitsA` whose train also calls at B
	 *   afterwards, unchanged and in their original order.
	 */
	function filterVisitsServingStop(visitsA, visitsB) {
		const callsAtB = new Map();
		for (const visit of visitsB) {
			if (!isUsableVisit(visit)) continue;
			const journey = visit.MonitoredVehicleJourney;
			for (const key of journeyKeys(journey)) {
				callsAtB.set(key, journey.MonitoredCall);
			}
		}
		return visitsA.filter((visit) => {
			if (!isUsableVisit(visit)) return false;
			const journey = visit.MonitoredVehicleJourney;
			for (const key of journeyKeys(journey)) {
				const callB = callsAtB.get(key);
				if (callB) return reachesBAfterA(journey.MonitoredCall, callB);
			}
			return false;
		});
	}

	/**
	 * @param {object} journey - A SIRI MonitoredVehicleJourney.
	 * @returns {string} Mission code (e.g. "SORO"), "" if absent.
	 */
	function journeyMission(journey) {
		const note = (journey.JourneyNote || [])[0];
		return note && note.value ? note.value : "";
	}

	/**
	 * @param {object} journey - A SIRI MonitoredVehicleJourney.
	 * @returns {string} Best available destination label, "" if none. SNCF
	 *   (RER/Transilien) journeys don't always carry DestinationDisplay (missing
	 *   or an empty array): fall back to DestinationName, then DirectionName.
	 */
	function journeyDestinationName(journey) {
		const candidates = [
			// biome-ignore lint/complexity/useOptionalChain: no `?.` (webpack 1)
			(journey.MonitoredCall || {}).DestinationDisplay,
			journey.DestinationName,
			journey.DirectionName,
		];
		for (const list of candidates) {
			const first = (list || [])[0] || {};
			if (first.value) return first.value;
		}
		return "";
	}

	/**
	 * @param {object[]} visits - MonitoredStopVisit list (already filtered for
	 *   an A->B trip).
	 * @param {number} now - Epoch ms.
	 * @returns {{journey: object, atStop: boolean, cancelled: boolean,
	 *   minutes: number, timeMs: ?number}[]} The departures with a usable
	 *   time, running trains first (a cancelled one can't hide the real next
	 *   departure), then at-stop first, then by time. `minutes` is floored at 0:
	 *   the expected time can be slightly past before VehicleAtStop flips.
	 */
	function rankDepartures(visits, now) {
		return visits
			.map((visit) => visit && visit.MonitoredVehicleJourney)
			.filter((journey) => journey && journey.MonitoredCall)
			.map((journey) => {
				const call = journey.MonitoredCall;
				const atStop = call.VehicleAtStop === true;
				const timeMs = callTimeMs(call);
				const minutes =
					timeMs === null ? null : Math.round((timeMs - now) / MINUTE_MS);
				return {
					journey: journey,
					atStop: atStop,
					cancelled: call.DepartureStatus === "cancelled",
					minutes: minutes === null ? null : Math.max(0, minutes),
					timeMs: timeMs,
					rank: atStop ? -1 : minutes,
				};
			})
			.filter((d) => d.atStop || d.minutes !== null)
			.sort(
				(a, b) => Number(a.cancelled) - Number(b.cancelled) || a.rank - b.rank
			);
	}

	const DEFAULT_CALL_GUARD = {
		maxCalls: 40,
		windowMinutes: 10,
		pauseMinutes: 15,
	};
	const MINUTE_MS = 60000;

	/**
	 * @param {*} value
	 * @param {number} min
	 * @param {number} fallback
	 * @returns {number} `value` as an integer >= min, or `fallback`.
	 */
	function intAtLeast(value, min, fallback) {
		const n = Math.floor(Number(value));
		return Number.isFinite(n) && n >= min ? n : fallback;
	}

	/**
	 * @param {object} [settings] - Config page's `callGuard` (may be missing
	 *   in configs saved before the guard existed).
	 * @returns {{maxCalls: number, windowMinutes: number, pauseMinutes: number}}
	 *   Sanitized settings. A positive maxCalls below 2 becomes 2: an A->B
	 *   refresh costs 2 calls at once and would otherwise never pass.
	 */
	function normalizeCallGuard(settings) {
		const s = settings || {};
		let maxCalls = intAtLeast(s.maxCalls, 0, DEFAULT_CALL_GUARD.maxCalls);
		if (maxCalls === 1) maxCalls = 2;
		return {
			maxCalls: maxCalls,
			windowMinutes: intAtLeast(
				s.windowMinutes,
				1,
				DEFAULT_CALL_GUARD.windowMinutes
			),
			pauseMinutes: intAtLeast(
				s.pauseMinutes,
				1,
				DEFAULT_CALL_GUARD.pauseMinutes
			),
		};
	}

	/**
	 * Decides whether a refresh may spend `count` PRIM calls now.
	 * @param {{calls: number[], pausedUntil: number}|null} state - Persisted
	 *   guard state (null on first use).
	 * @param {object} [settings] - Raw `callGuard` settings.
	 * @param {number} now - Epoch ms.
	 * @param {number} count - Calls this refresh needs (1, or 2 for A->B).
	 * @returns {{allowed: boolean, minutesLeft: number,
	 *   state: {calls: number[], pausedUntil: number}}} `state` is the new
	 *   state to persist; `minutesLeft` (rounded up) is only meaningful when
	 *   refused.
	 */
	function decideCallGuard(state, settings, now, count) {
		const s = normalizeCallGuard(settings);
		if (s.maxCalls === 0) {
			return {
				allowed: true,
				minutesLeft: 0,
				state: { calls: [], pausedUntil: 0 },
			};
		}
		let pausedUntil = (state && state.pausedUntil) || 0;
		// A pause can't legitimately end later than pauseMinutes from now --
		// if it does, the phone clock moved backwards: drop it rather than
		// pausing for hours.
		if (pausedUntil - now > s.pauseMinutes * MINUTE_MS) pausedUntil = 0;
		if (pausedUntil > now) {
			return {
				allowed: false,
				minutesLeft: Math.ceil((pausedUntil - now) / MINUTE_MS),
				state: { calls: [], pausedUntil: pausedUntil },
			};
		}
		const windowStart = now - s.windowMinutes * MINUTE_MS;
		const calls = ((state && state.calls) || []).filter((t) => t > windowStart);
		if (calls.length + count > s.maxCalls) {
			return {
				allowed: false,
				minutesLeft: s.pauseMinutes,
				state: { calls: [], pausedUntil: now + s.pauseMinutes * MINUTE_MS },
			};
		}
		for (let i = 0; i < count; i++) calls.push(now);
		return {
			allowed: true,
			minutesLeft: 0,
			state: { calls: calls, pausedUntil: 0 },
		};
	}

	/**
	 * @param {object} [before] - Previously saved raw `callGuard` settings.
	 * @param {object} [after] - Newly saved raw `callGuard` settings.
	 * @returns {boolean} True when the effective (normalized) settings differ
	 *   -- the caller then resets the persisted guard state, so a pause
	 *   started under the old settings doesn't outlive them.
	 */
	function callGuardSettingsChanged(before, after) {
		const a = normalizeCallGuard(before);
		const b = normalizeCallGuard(after);
		return (
			a.maxCalls !== b.maxCalls ||
			a.windowMinutes !== b.windowMinutes ||
			a.pauseMinutes !== b.pauseMinutes
		);
	}

	// Last good times older than this aren't worth showing as a fallback.
	const STALE_MAX_AGE_MINUTES = 30;

	/**
	 * Builds the fallback shown when a refresh fails (network, quota, call-guard
	 * pause): the trip's last good departure fields plus how old they are.
	 * @param {{at: number, extra: object}|null|undefined} saved - Last good
	 *   reply for the trip, as stored by pkjs.
	 * @param {number} now - Epoch ms.
	 * @returns {object|null} `extra` plus `staleAge` (whole minutes), or null
	 *   when nothing usable was saved (none, or older than the max age).
	 */
	function staleExtra(saved, now) {
		if (!saved || typeof saved.at !== "number" || !saved.extra) return null;
		const ageMinutes = Math.floor((now - saved.at) / MINUTE_MS);
		// A negative age means the phone clock moved backwards: don't trust it.
		if (ageMinutes < 0 || ageMinutes > STALE_MAX_AGE_MINUTES) return null;
		return Object.assign({}, saved.extra, { staleAge: ageMinutes });
	}

	module.exports = {
		callTimeMs: callTimeMs,
		journeyDestinationName: journeyDestinationName,
		rankDepartures: rankDepartures,
		staleExtra: staleExtra,
		filterVisitsServingStop: filterVisitsServingStop,
		journeyMission: journeyMission,
		DEFAULT_CALL_GUARD: DEFAULT_CALL_GUARD,
		normalizeCallGuard: normalizeCallGuard,
		decideCallGuard: decideCallGuard,
		callGuardSettingsChanged: callGuardSettingsChanged,
	};
	return module.exports;
})();

// StroyCommute's plugin: the next departures of the trips tracked in the
// app's settings, as the source transit/departure, so any watchface (or
// Index) can show them. Pebble app plugins are a preview feature: the
// plugin only runs while something reads its source, and is started fresh
// for each request (state lives in localStorage, shared with pkjs).
//
// This file is the plugin's own code. The script the SDK bundles,
// src/plugin/plugin.js, is generated from it plus src/pkjs/trips.js (the
// SDK copies a plugin script as is, without require()): run
// `npm run sync:plugin` after changing either.
//
// PRIM quota: a watchface can read the source all day, so the plugin
// shares the app's call guard and daily count (same localStorage keys),
// fetches a trip at most every MIN_FETCH_MS, serves at most MAX_TRIPS trips
// and stops fetching when the day's remaining quota falls under
// QUOTA_RESERVE, leaving it to the app. It answers from its cache then.

/* global trips */

const CONFIG_KEY = "stroycommuteConfig";
const CACHE_KEY = "stroycommutePluginCache";
// trip key -> when the plugin last called PRIM for it, answer or not: a
// watchface reads the source on every change, and without this a failed or
// empty answer (no departure at night) was fetched again on each read.
const TRIED_KEY = "stroycommutePluginTried";
const QUOTA_KEY = "stroycommuteQuota";
const GUARD_KEY = "stroycommuteCallGuard";
const STOP_MONITORING_URL =
	"https://prim.iledefrance-mobilites.fr/marketplace/stop-monitoring";
const MIN_FETCH_MS = 2 * 60000;
const MAX_TRIPS = 3;
const PRIM_DAILY_QUOTA = 1000;
const QUOTA_RESERVE = 300;
// Times older than this aren't served at all.
const MAX_AGE_MS = 30 * 60000;

const TEXTS = {
	fr: { atStop: "À quai", towards: "Vers", minutes: "min" },
	en: { atStop: "At stop", towards: "To", minutes: "min" },
};

/** @returns {*} The parsed localStorage value, `fallback` if missing/garbled. */
function readJson(key, fallback) {
	try {
		const raw = localStorage.getItem(key);
		return raw ? JSON.parse(raw) : fallback;
	} catch (_error) {
		return fallback;
	}
}

/** @returns {string} The trip's key, as pkjs and the watch build it. */
function tripKey(stop) {
	return [stop.stopRef, stop.lineRef, stop.destStopRef || ""].join("|");
}

/** @returns {number} PRIM calls left today by the app's own count. */
function quotaLeft(now) {
	const today = new Date(now).toISOString().slice(0, 10);
	const state = readJson(QUOTA_KEY, null);
	const used = state && state.date === today ? state.count : 0;
	return PRIM_DAILY_QUOTA - used;
}

/** Adds one call to the app's daily count (see pkjs). */
function countCall(now) {
	const today = new Date(now).toISOString().slice(0, 10);
	let state = readJson(QUOTA_KEY, null);
	if (!state || state.date !== today) state = { date: today, count: 0 };
	state.count += 1;
	localStorage.setItem(QUOTA_KEY, JSON.stringify(state));
}

/**
 * @returns {Promise<?object[]>} The stop's MonitoredStopVisit list, null on
 *   any failure (network, quota, bad key or stop).
 */
async function fetchVisits(apiKey, ref, lineRef, now) {
	const url = `${STOP_MONITORING_URL}?MonitoringRef=${encodeURIComponent(ref)}&LineRef=${encodeURIComponent(lineRef)}`;
	countCall(now);
	// One line per PRIM call, to check the plugin's pace in `pebble logs`.
	console.log(`plugin: stop-monitoring ${ref} ${lineRef}`);
	// No timeout of our own: the Pebble app refuses setTimeout to plugins
	// (it threw on every call), and its plugin host already gives up on a
	// request that doesn't answer.
	return fetch(url, { headers: { apiKey: apiKey } })
		.then((response) => {
			if (!response.ok)
				console.log(`plugin: HTTP ${response.status} for ${ref}`);
			return response.ok ? response.json() : null;
		})
		.then((body) => {
			if (!body) return null;
			const delivery = body.Siri.ServiceDelivery.StopMonitoringDelivery[0];
			const visits = delivery.MonitoredStopVisit || [];
			console.log(`plugin: ${visits.length} visits for ${ref}`);
			return visits;
		})
		.catch((error) => {
			console.log(`plugin: failed for ${ref}: ${error}`);
			return null;
		});
}

/**
 * @param {object[]} visits - Already filtered for an A->B trip.
 * @param {number} now
 * @returns {?object} What the source serves for a trip, null if no
 *   departure has a usable time.
 */
function summarize(visits, now) {
	const departures = trips.rankDepartures(visits, now);
	if (departures.length === 0) return null;
	const first = departures[0];
	const second =
		departures.length > 1 && !departures[1].cancelled ? departures[1] : null;
	return {
		at: now,
		atStop: first.atStop,
		cancelled: first.cancelled,
		time: first.timeMs,
		time2: second ? second.timeMs : null,
		destination: trips.journeyDestinationName(first.journey),
		mission: trips.journeyMission(first.journey),
	};
}

/**
 * @returns {Promise<?object>} Fresh times for `stop`, null when PRIM
 *   answers without a usable departure, or the cached ones when fetching
 *   isn't allowed right now or fails.
 */
async function tripTimes(config, stop, cached, now) {
	if (cached && now - cached.at < MIN_FETCH_MS) return cached;
	const tried = readJson(TRIED_KEY, {});
	if (now - (tried[tripKey(stop)] || 0) < MIN_FETCH_MS) return cached;
	if (quotaLeft(now) < QUOTA_RESERVE) return cached;
	const refs = stop.destStopRef
		? [stop.stopRef, stop.destStopRef]
		: [stop.stopRef];
	if (refs.some((ref) => /:monomodalStopPlace:$/.test(ref))) return null;
	const guard = trips.decideCallGuard(
		readJson(GUARD_KEY, null),
		config.callGuard,
		now,
		refs.length
	);
	localStorage.setItem(GUARD_KEY, JSON.stringify(guard.state));
	if (!guard.allowed) return cached;
	// Written before the calls, so reads arriving meanwhile don't call too.
	const triedNow = readJson(TRIED_KEY, {});
	triedNow[tripKey(stop)] = now;
	localStorage.setItem(TRIED_KEY, JSON.stringify(triedNow));
	const results = await Promise.all(
		refs.map((ref) => fetchVisits(config.apiKey, ref, stop.lineRef, now))
	);
	if (results.some((visits) => visits === null)) return cached;
	const kept = stop.destStopRef
		? trips.filterVisitsServingStop(results[0], results[1])
		: results[0];
	const times = summarize(kept, now);
	if (!times) {
		console.log(
			`plugin: no usable departure for ${tripKey(stop)} (${kept.length} kept)`
		);
	}
	// PRIM answered: no departure means none, not "keep the last train"
	// (which has left). Only a failed call keeps the cached times.
	return times;
}

/** @returns {{shortText: {text: string}}} */
function short(text) {
	return { shortText: { text: String(text).slice(0, 7) } };
}

/** @returns {number} Whole minutes from now until `timeMs`, at least 0. */
function minutesUntil(timeMs, now) {
	return Math.max(0, Math.round((timeMs - now) / 60000));
}

/** @returns {object} The source's properties for one trip. */
function propertiesOf(stop, times, texts, now) {
	const title = stop.destStopName
		? `${stop.lineName} — ${stop.stopName} > ${stop.destStopName}`
		: `${stop.lineName} — ${stop.stopName}`;
	const properties = {
		name: Object.assign(short(stop.lineName), { longText: { text: title } }),
		line: short(stop.lineName),
		stop: { longText: { text: stop.stopName } },
	};
	if (times.destination) {
		properties.destination = {
			longText: { text: `${texts.towards} ${times.destination}` },
		};
	}
	if (times.atStop) {
		properties.next = {
			shortText: { text: texts.atStop },
			longText: { text: texts.atStop },
			numericValue: { value: 0, unit: "min" },
		};
	} else if (typeof times.time === "number") {
		const minutes = minutesUntil(times.time, now);
		const label = `${minutes} ${texts.minutes}`;
		properties.next = {
			shortText: { text: label },
			longText: {
				text: times.destination ? `${label} — ${times.destination}` : label,
			},
			numericValue: { value: minutes, unit: "min" },
		};
		properties.next_time = {
			timestamp: { value: Math.floor(times.time / 1000) },
		};
	}
	if (typeof times.time2 === "number") {
		const label = `${minutesUntil(times.time2, now)} ${texts.minutes}`;
		properties.following = {
			shortText: { text: label },
			longText: { text: label },
		};
		properties.following_time = {
			timestamp: { value: Math.floor(times.time2 / 1000) },
		};
	}
	return properties;
}

Pebble.registerSourceHandler(async (request, respond) => {
	if (request.category !== "transit" || request.item !== "departure") {
		respond.error("INVALID_REQUEST");
		return;
	}
	const now = Date.now();
	const config = readJson(CONFIG_KEY, null);
	if (!config || !config.apiKey || config.pluginEnabled === false) {
		respond.data({ validUntilMs: now + MIN_FETCH_MS, instances: [] });
		return;
	}
	const texts = config.language === "en" ? TEXTS.en : TEXTS.fr;
	const stops = (config.trackedStops || []).slice(0, MAX_TRIPS);
	const cache = readJson(CACHE_KEY, {});
	const results = await Promise.all(
		stops.map((stop) =>
			tripTimes(config, stop, cache[tripKey(stop)] || null, now).catch(
				(error) => {
					console.log(`plugin: ${tripKey(stop)} failed: ${error}`);
					return cache[tripKey(stop)] || null;
				}
			)
		)
	);
	const nextCache = {};
	const instances = [];
	stops.forEach((stop, i) => {
		const times = results[i];
		if (!times || now - times.at > MAX_AGE_MS) return;
		nextCache[tripKey(stop)] = times;
		instances.push({
			instanceId: tripKey(stop),
			properties: propertiesOf(stop, times, texts, now),
		});
	});
	localStorage.setItem(CACHE_KEY, JSON.stringify(nextCache));
	// Read again within the minute, so the countdown texts move on.
	respond.data({ validUntilMs: now + 60000, instances: instances });
});
